/**
 * T-600: the landing page's template catalogue, generated by the drafting
 * workspace (`yarn workspace @lawie/drafting export:catalogue`) into the
 * committed src/data/landing-catalogue.json. Never edit that file by hand;
 * a drafting drift test fails when it is stale.
 */
import data from '@/data/landing-catalogue.json';

export interface LandingTemplate {
  id: string;
  name: string;
}

export interface LandingCategory {
  id: string;
  name: string;
  /** T-239 row number; the categories are already in this order. */
  order: number;
  templates: LandingTemplate[];
}

export interface LandingCatalogue {
  generatedAt: string;
  categories: LandingCategory[];
  /** Number of templates shown, the sum over `categories`. */
  total: number;
}

export const landingCatalogue: LandingCatalogue = data;

/**
 * The headline number: `total` rounded down to the nearest ten, with "+"
 * (86 -> "80+"), so one template more or less never makes the copy wrong
 * (Arjun, T-584 spec §11). Not a finite number, or below 0, counts as 0.
 */
export function headlineCount(total: number): string {
  const n = Number.isFinite(total) && total > 0 ? total : 0;
  return `${Math.floor(n / 10) * 10}+`;
}
